ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t compact_index = 0;
    size_t pixel_index = 0;

    while (number_compact_pixels > 0 && pixel_index < number_pixels) {
        unsigned char byte = compact_pixels[compact_index];

        for (ssize_t i = 0; i < 8 / depth && pixel_index < number_pixels; ++i) {
            unsigned char value = (byte >> (8 - depth)) & ((1 << depth) - 1);
            pixels[pixel_index++] = value;
            byte <<= depth;
        }

        ++compact_index;
        --number_compact_pixels;
    }

    return (ssize_t)pixel_index;
}

ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels,
                            ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t compact_index = 0;
    size_t pixel_index = 0;
    size_t bits_per_unit = 0;

    switch (depth) {
        case 1:
            bits_per_unit = 8;
            break;
        case 2:
            bits_per_unit = 4;
            break;
        case 4:
            bits_per_unit = 2;
            break;
        default:
            return -1; // Invalid depth
    }

    size_t compact_units_per_pixel = 8 / bits_per_unit;
    size_t total_compact_units_needed = number_pixels / compact_units_per_pixel;
    if ((number_pixels % compact_units_per_pixel) != 0) {
        total_compact_units_needed++;
    }

    if (number_compact_pixels < total_compact_units_needed) {
        return -1; // Insufficient compact pixel data
    }

    while (pixel_index < number_pixels) {
        unsigned char compact_unit = compact_pixels[compact_index];
        for (size_t bit_offset = 0; bit_offset < 8 && pixel_index < number_pixels; bit_offset += depth) {
            unsigned char pixel_value = (compact_unit >> bit_offset) & ((1 << depth) - 1);
            pixels[pixel_index++] = pixel_value;
        }
        compact_index++;
    }

    return (ssize_t)pixel_index;
}

ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t compact_index = 0;
    size_t output_index = 0;

    while (number_compact_pixels > 0 && output_index < number_pixels) {
        switch (depth) {
            case 1:
                for (size_t i = 0; i < 8 && number_compact_pixels > 0 && output_index < number_pixels; ++i, ++output_index, ++compact_index) {
                    pixels[output_index] = (compact_pixels[compact_index] >> (7 - i)) & 0x01;
                    --number_compact_pixels;
                }
                break;
            case 2:
                for (size_t i = 0; i < 4 && number_compact_pixels > 0 && output_index < number_pixels; ++i, ++compact_index) {
                    pixels[output_index++] = (compact_pixels[compact_index] >> 6) & 0x03;
                    if (output_index >= number_pixels) break;
                    pixels[output_index++] = (compact_pixels[compact_index] >> 4) & 0x03;
                    if (output_index >= number_pixels) break;
                    pixels[output_index++] = (compact_pixels[compact_index] >> 2) & 0x03;
                    if (output_index >= number_pixels) break;
                    pixels[output_index++] = (compact_pixels[compact_index] & 0x03);
                    --number_compact_pixels;
                }
                break;
            case 4:
                for (size_t i = 0; i < 2 && number_compact_pixels > 0 && output_index < number_pixels; ++i, ++compact_index) {
                    pixels[output_index++] = (compact_pixels[compact_index] >> 4) & 0x0F;
                    if (output_index >= number_pixels) break;
                    pixels[output_index++] = (compact_pixels[compact_index] & 0x0F);
                    --number_compact_pixels;
                }
                break;
            default:
                return -1;
        }
    }

    return (ssize_t) (number_pixels - output_index);
}

ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t src_index = 0;
    size_t dst_index = 0;
    size_t bits_remaining = number_compact_pixels * 8;
    size_t bits_per_pixel = depth;

    if (bits_per_pixel == 0 || bits_remaining < number_pixels * bits_per_pixel)
        return -1;

    while (bits_remaining >= bits_per_pixel && dst_index < number_pixels) {
        unsigned char pixel_value = 0;
        size_t bits_to_read = bits_per_pixel;
        size_t current_byte = src_index / 8;
        size_t bit_offset = src_index % 8;

        while (bits_to_read > 0 && current_byte < number_compact_pixels) {
            size_t bits_in_byte = 8 - bit_offset;
            size_t bits_to_copy = (bits_in_byte < bits_to_read) ? bits_in_byte : bits_to_read;
            unsigned char mask = (0xFF << (8 - bits_to_copy)) >> (8 - bits_to_read);
            pixel_value |= ((compact_pixels[current_byte] >> (8 - bits_to_copy)) & mask) << (bits_per_pixel - bits_to_read);
            bits_to_read -= bits_to_copy;
            bit_offset += bits_to_copy;
            current_byte = bit_offset / 8;
            bit_offset %= 8;
        }

        pixels[dst_index++] = pixel_value;
        src_index += bits_per_pixel;
        bits_remaining -= bits_per_pixel;
    }

    return dst_index;
}

ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t compact_index = 0;
    size_t pixel_index = 0;
    size_t compact_bytes = 0;

    if (depth == 1) {
        compact_bytes = (number_compact_pixels + 7) / 8;
    } else if (depth == 2) {
        compact_bytes = (number_compact_pixels + 3) / 4;
    } else if (depth == 4) {
        compact_bytes = (number_compact_pixels + 1) / 2;
    } else {
        return -1; // Invalid depth
    }

    for (size_t i = 0; i < number_compact_pixels && compact_index < compact_bytes && pixel_index < number_pixels; ++i) {
        unsigned char byte = compact_pixels[compact_index];
        unsigned char value = 0;

        if (depth == 1) {
            size_t bit = i % 8;
            value = (byte >> bit) & 1;
            compact_index += (bit == 7);
        } else if (depth == 2) {
            size_t bit = i % 4;
            value = (byte >> (2 * bit)) & 3;
            compact_index += (bit == 3);
        } else if (depth == 4) {
            size_t bit = i % 2;
            value = (byte >> (4 * bit)) & 15;
            compact_index += (bit == 1);
        }

        pixels[pixel_index++] = value;
    }

    return pixel_index;
}
